def is_pg():
    return bool(DATABASE_URL and psycopg2)

def conn():
    if is_pg():
        return psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)
    c=sqlite3.connect("basma_store.db")
    c.row_factory=sqlite3.Row
    return c

def qmark(sql):
    return sql.replace("?", "%s") if is_pg() else sql

def fetchall(c, sql, params=()):
    cur=c.cursor(); cur.execute(qmark(sql), params); return cur.fetchall()

def fetchone(c, sql, params=()):
    cur=c.cursor(); cur.execute(qmark(sql), params); return cur.fetchone()

def execute(c, sql, params=()):
    cur=c.cursor(); cur.execute(qmark(sql), params); return cur

def init_db():
    c=conn()
    if is_pg():
        execute(c, """CREATE TABLE IF NOT EXISTS products(
        id SERIAL PRIMARY KEY,name TEXT NOT NULL,brand TEXT,description TEXT,
        regular_price REAL NOT NULL,sale_price REAL NOT NULL,types TEXT,
        top_notes TEXT,heart_notes TEXT,base_notes TEXT,longevity INTEGER DEFAULT 3,
        projection INTEGER DEFAULT 3,concentration TEXT,seasons TEXT,occasions TEXT,
        active INTEGER DEFAULT 1,featured INTEGER DEFAULT 0)""")
        execute(c, """CREATE TABLE IF NOT EXISTS variants(
        id SERIAL PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
        label TEXT NOT NULL,volume_ml INTEGER,price REAL NOT NULL,stock INTEGER NOT NULL DEFAULT 0,active INTEGER DEFAULT 1)""")
        execute(c, """CREATE TABLE IF NOT EXISTS orders(
        id SERIAL PRIMARY KEY,order_no TEXT UNIQUE NOT NULL,customer_name TEXT NOT NULL,phone TEXT NOT NULL,
        governorate TEXT NOT NULL,area TEXT NOT NULL,address TEXT NOT NULL,notes TEXT,payment_method TEXT NOT NULL,
        transfer_reference TEXT,subtotal REAL NOT NULL,shipping_fee REAL NOT NULL,total REAL NOT NULL,
        status TEXT NOT NULL,inventory_deducted INTEGER DEFAULT 0,created_at TEXT NOT NULL)""")
        execute(c, """CREATE TABLE IF NOT EXISTS order_items(
        id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
        product_id INTEGER NOT NULL REFERENCES products(id),variant_id INTEGER REFERENCES variants(id),
        product_name TEXT NOT NULL,variant_label TEXT,unit_price REAL NOT NULL,qty INTEGER NOT NULL)""")
    else:
        c.executescript("""CREATE TABLE IF NOT EXISTS products(
        id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,brand TEXT,description TEXT,regular_price REAL NOT NULL,
        sale_price REAL NOT NULL,types TEXT,top_notes TEXT,heart_notes TEXT,base_notes TEXT,longevity INTEGER DEFAULT 3,
        projection INTEGER DEFAULT 3,concentration TEXT,seasons TEXT,occasions TEXT,active INTEGER DEFAULT 1,featured INTEGER DEFAULT 0);
        CREATE TABLE IF NOT EXISTS variants(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,label TEXT NOT NULL,
        volume_ml INTEGER,price REAL NOT NULL,stock INTEGER NOT NULL DEFAULT 0,active INTEGER DEFAULT 1);
        CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,order_no TEXT UNIQUE NOT NULL,customer_name TEXT NOT NULL,
        phone TEXT NOT NULL,governorate TEXT NOT NULL,area TEXT NOT NULL,address TEXT NOT NULL,notes TEXT,payment_method TEXT NOT NULL,
        transfer_reference TEXT,subtotal REAL NOT NULL,shipping_fee REAL NOT NULL,total REAL NOT NULL,status TEXT NOT NULL,
        inventory_deducted INTEGER DEFAULT 0,created_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,
        variant_id INTEGER,product_name TEXT NOT NULL,variant_label TEXT,unit_price REAL NOT NULL,qty INTEGER NOT NULL);""")
    count=fetchone(c,"SELECT COUNT(*) AS n FROM products")
    n = count["n"] if hasattr(count,"keys") else count[0]
    if n==0:
        seeds=[
        ("Pure Musc","Narciso Rodriguez","مسك نظيف ناعم بلمسة بودرية أنيقة.",450,420,"musk,floral,powdery","زهر البرتقال","مسك، زهور بيضاء","كشمير، عنبر",4,3,"EDP","الربيع,الخريف","يومي,عمل",1,1),
        ("Musk Powder","Ibraq","بودري مسكي ناعم بحلاوة خفيفة.",340,310,"musk,powdery,sweet","بودرة نظيفة","مسك أبيض","فانيليا، أخشاب",4,3,"EDP","الخريف,الشتاء","يومي,عمل",1,1),
        ("Amber Silk","Basma Selection","عنبر دافئ وفانيليا بطابع راقٍ.",430,390,"amber,vanilla","توابل خفيفة","عنبر، فانيليا","أخشاب دافئة",5,4,"Parfum","الخريف,الشتاء","سهرة,مناسبات",1,1),
        ("Citrus Neroli","Basma Selection","حمضيات ونيرولي بانتعاش واضح.",375,340,"citrus,fresh,floral","برغموت، ليمون","نيرولي","مسك، أخشاب",3,3,"EDP","الصيف,الربيع","يومي,عمل",1,0)]
        for s in seeds:
            cur=execute(c,"""INSERT INTO products(name,brand,description,regular_price,sale_price,types,top_notes,heart_notes,base_notes,longevity,projection,concentration,seasons,occasions,active,featured)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",s)
            pid = cur.lastrowid if not is_pg() else cur.fetchone()[0] if False else None
            if is_pg():
                pid=fetchone(c,"SELECT currval(pg_get_serial_sequence('products','id')) AS id")["id"]
            for label,ml,mult,st in [("3 ML",3,.28,6),("5 ML",5,.42,5),("10 ML",10,.74,4),("الزجاجة",50,1,3)]:
                execute(c,"INSERT INTO variants(product_id,label,volume_ml,price,stock,active) VALUES(?,?,?,?,?,1)",(pid,label,ml,round(s[4]*mult),st))
    c.commit(); c.close()

