def page(title, body, admin=False):
    return f"""<!doctype html><html lang='ar' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{title}</title><style>{CSS}</style></head><body>
<div class='top'>✨ شحن مجاني للطلبات من 700 ج فأكثر</div><header><a class='brand' href='/'><img class='logo' src='{LOGO}'>Basma Store</a><div class='nav'><a class='chip' href='/track'>تتبع الطلب</a><a class='chip' href='/cart'>السلة</a></div></header>
{body}</body></html>"""

def rows_dict(rows):
    return [dict(r) for r in rows]

@app.before_request
def ensure_db():
    init_db()

@app.get("/")
def home():
    c=conn(); products=fetchall(c,"SELECT * FROM products WHERE active=1 ORDER BY featured DESC,id DESC"); c.close()
    cards="".join([f"<a class='card' href='/product/{p['id']}'><div class='pic'>{p['name']}</div><h3>{p['name']}</h3><small>{p['brand'] or ''}</small><p>{p['description'] or ''}</p><div class='price'>{int(p['sale_price'])} ج</div></a>" for p in rows_dict(products)])
    body=f"<section class='hero'><div><small>PERFUME STORE</small><h1>أهلاً بك في<br>Basma Store</h1><p>عالم العطور بين يديك… كل ما تحتاجه في مكان واحد.</p></div><img src='{LOGO}'></section><section class='wrap'><h2>العطور</h2><div class='grid'>{cards}</div></section>"
    return page("Basma Store",body)

@app.get("/product/<int:pid>")
def product(pid):
    c=conn(); p=fetchone(c,"SELECT * FROM products WHERE id=? AND active=1",(pid,)); vs=fetchall(c,"SELECT * FROM variants WHERE product_id=? AND active=1 ORDER BY volume_ml",(pid,)); c.close()
    if not p: return "Not found",404
    p=dict(p); vs=rows_dict(vs)
    opts="".join([f"<option value='{v['id']}'>{v['label']} — {int(v['price'])} ج — متاح {v['stock']}</option>" for v in vs])
    body=f"""<section class='wrap'><div class='panel'><h1>{p['name']}</h1><b>{p['brand'] or ''}</b><p>{p['description'] or ''}</p><div class='price'>{int(p['sale_price'])} ج</div>
<form method='post' action='/cart/add'><input type='hidden' name='product_id' value='{pid}'><div class='field'><label>الحجم</label><select name='variant_id'>{opts}</select></div><div class='field'><label>الكمية</label><input type='number' name='qty' value='1' min='1'></div><button class='btn'>أضف للسلة</button></form></div>
<div class='panel'><h2>الهرم العطري</h2><p><b>الافتتاحية:</b> {p['top_notes'] or '—'}</p><p><b>القلب:</b> {p['heart_notes'] or '—'}</p><p><b>القاعدة:</b> {p['base_notes'] or '—'}</p><p><b>التركيز:</b> {p['concentration'] or '—'}</p></div></section>"""
    return page(p["name"],body)

