    c=conn(); r=fetchone(c,"SELECT p.name,v.label,v.price,v.stock FROM variants v JOIN products p ON p.id=v.product_id WHERE p.id=? AND v.id=?",(pid,vid)); c.close()
    if not r: return redirect("/")
    r=dict(r); cart=session.get("cart",[]); key=f"{pid}:{vid}"
    found=next((x for x in cart if x["key"]==key),None)
    existing=found["qty"] if found else 0
    if existing+qty>int(r["stock"]): flash("الكمية غير متاحة"); return redirect(f"/product/{pid}")
    if found: found["qty"]+=qty
    else: cart.append({"key":key,"product_id":pid,"variant_id":vid,"name":r["name"],"variant":r["label"],"price":float(r["price"]),"qty":qty})
