@app.get("/cart")
def cart():
    cart=session.get("cart",[]); sub=sum(x["price"]*x["qty"] for x in cart)
    items="".join([f"<tr><td>{x['name']}</td><td>{x['variant']}</td><td>{x['qty']}</td><td>{int(x['price']*x['qty'])} ج</td></tr>" for x in cart])
    remain=max(0,FREE_SHIPPING_AT-sub)
    body=f"<section class='wrap'><h1>السلة</h1><div class='panel'><table><tr><th>العطر</th><th>الحجم</th><th>الكمية</th><th>السعر</th></tr>{items}</table><h2>الإجمالي: {int(sub)} ج</h2><p>{'مؤهل للشحن المجاني 🎉' if remain==0 else 'متبقي '+str(int(remain))+' ج للشحن المجاني'}</p><a class='btn' href='/checkout'>إتمام الطلب</a></div></section>"
    return page("السلة",body)

@app.route("/checkout",methods=["GET","POST"])
def checkout():
    cart=session.get("cart",[])
    if not cart: return redirect("/")
    sub=sum(x["price"]*x["qty"] for x in cart)
    if request.method=="POST":
        name=request.form["name"].strip(); phone=request.form["phone"].strip(); gov=request.form["governorate"]; area=request.form["area"].strip(); address=request.form["address"].strip(); payment=request.form["payment"]
        shipping=0 if sub>=FREE_SHIPPING_AT else GOV_FEES.get(gov,0); total=sub+shipping
        no="BS-"+datetime.now().strftime("%y%m%d%H%M%S"); status="awaiting_customer_confirmation" if payment=="cod" else "awaiting_payment_confirmation"
        c=conn()
        cur=execute(c,"""INSERT INTO orders(order_no,customer_name,phone,governorate,area,address,payment_method,subtotal,shipping_fee,total,status,created_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",(no,name,phone,gov,area,address,payment,sub,shipping,total,status,datetime.now().isoformat(timespec="seconds")))
        oid=cur.lastrowid if not is_pg() else fetchone(c,"SELECT currval(pg_get_serial_sequence('orders','id')) AS id")["id"]
        for x in cart: execute(c,"INSERT INTO order_items(order_id,product_id,variant_id,product_name,variant_label,unit_price,qty) VALUES(?,?,?,?,?,?,?)",(oid,x["product_id"],x["variant_id"],x["name"],x["variant"],x["price"],x["qty"]))
        c.commit(); c.close(); session["cart"]=[]
        return page("تم الطلب",f"<section class='wrap'><div class='panel'><h1>تم استلام طلبك ✓</h1><p>رقم الطلب: <b>{no}</b></p><p>الإجمالي: <b>{int(total)} ج</b></p><a class='btn' href='/track'>تتبع الطلب</a></div></section>")
    opts="".join([f"<option>{g}</option>" for g in GOV_FEES])
    body=f"""<section class='wrap'><h1>إتمام الطلب</h1><form class='panel' method='post'><div class='field'><label>الاسم</label><input name='name' required></div><div class='field'><label>الموبايل</label><input name='phone' required></div><div class='field'><label>المحافظة</label><select name='governorate'>{opts}</select></div><div class='field'><label>المدينة / المنطقة</label><input name='area' required></div><div class='field'><label>العنوان بالتفصيل</label><textarea name='address' required></textarea></div><div class='field'><label>طريقة الدفع</label><select name='payment'><option value='cod'>الدفع عند الاستلام</option><option value='instapay'>InstaPay</option></select></div><button class='btn'>تأكيد الطلب</button></form></section>"""
    return page("إتمام الطلب",body)

@app.route("/track",methods=["GET","POST"])
def track():
    result=""
    if request.method=="POST":
        c=conn(); o=fetchone(c,"SELECT * FROM orders WHERE order_no=?",(request.form["order_no"].strip(),)); c.close()
        if o:
            o=dict(o); result=f"<div class='panel'><h3>{o['order_no']}</h3><p>الحالة: <b>{o['status']}</b></p><p>الإجمالي: {int(o['total'])} ج</p></div>"
        else: result="<div class='panel'>لم يتم العثور على الطلب.</div>"
    body=f"<section class='wrap'><h1>تتبع طلبك</h1><form class='panel' method='post'><div class='field'><input name='order_no' placeholder='رقم الطلب' required></div><button class='btn'>تتبع</button></form>{result}</section>"
    return page("تتبع الطلب",body)

