@app.get("/admin")
def admin():
    if not session.get("admin"): return redirect("/admin/login")
    c=conn(); orders=fetchall(c,"SELECT * FROM orders ORDER BY id DESC"); products=fetchall(c,"SELECT * FROM products ORDER BY id DESC"); c.close()
    orows="".join([f"<tr><td>{o['order_no']}</td><td>{o['customer_name']}</td><td>{int(o['total'])}</td><td>{o['status']}</td><td><form method='post' action='/admin/order/{o['id']}/confirm'><button>تأكيد</button></form></td></tr>" for o in rows_dict(orders)])
    prows="".join([f"<tr><td>{p['name']}</td><td>{int(p['sale_price'])} ج</td></tr>" for p in rows_dict(products)])
    body=f"<section class='wrap'><h1>لوحة التحكم</h1><div class='panel'><h2>الطلبات</h2><table><tr><th>رقم</th><th>العميل</th><th>الإجمالي</th><th>الحالة</th><th></th></tr>{orows}</table></div><div class='panel'><h2>المنتجات</h2><table>{prows}</table></div></section>"
    return page("الإدارة",body)

@app.post("/admin/order/<int:oid>/confirm")
def confirm_order(oid):
    if not session.get("admin"): return redirect("/admin/login")
    c=conn(); order=fetchone(c,"SELECT * FROM orders WHERE id=?",(oid,))
    if order and not int(order["inventory_deducted"]):
        items=fetchall(c,"SELECT * FROM order_items WHERE order_id=?",(oid,))
        for it in items:
            v=fetchone(c,"SELECT stock FROM variants WHERE id=?",(it["variant_id"],))
            if not v or int(v["stock"])<int(it["qty"]): c.close(); return "Stock insufficient",400
        for it in items: execute(c,"UPDATE variants SET stock=stock-? WHERE id=?",(it["qty"],it["variant_id"]))
        execute(c,"UPDATE orders SET inventory_deducted=1,status='confirmed' WHERE id=?",(oid,))
        c.commit()
    c.close(); return redirect("/admin")

